#!/usr/bin/env node

/**
 * Automatically merge WASM type definitions from all modules
 * This script reads the auto-generated .d.ts files from each WASM module
 * and creates a unified type definition file.
 */

const fs = require("fs")
const path = require("path")

const WASM_DIST = path.join(__dirname, "../rust-wasm/wasm-dist")
const OUTPUT_FILE = path.join(__dirname, "../wasm-dist/roo_core_wasm.d.ts")

const MODULES = [
	{ name: "task-engine", file: "roo_task_engine.d.ts" },
	{ name: "tools", file: "roo_tools.d.ts" },
	{ name: "api-integration", file: "roo_api_integration.d.ts" },
	{ name: "conversation", file: "roo_conversation.d.ts" },
	{ name: "memory", file: "roo_memory.d.ts" },
]

function extractExports(content) {
	// Remove wasm import and default export lines
	const lines = content.split("\n").filter((line) => {
		return (
			!line.includes("wasm_bindgen") &&
			!line.startsWith("export default") &&
			!line.includes("import.meta.url") &&
			line.trim() !== ""
		)
	})
	return lines.join("\n")
}

function generateUnifiedTypes() {
	let output = `/**
 * Unified WASM Type Definitions
 * 
 * Auto-generated by scripts/merge-wasm-types.js
 * DO NOT EDIT MANUALLY - Run 'node scripts/merge-wasm-types.js' to regenerate
 */

`

	// Process each module
	for (const module of MODULES) {
		const modulePath = path.join(WASM_DIST, module.name, module.file)

		if (!fs.existsSync(modulePath)) {
			console.warn(`⚠️  Warning: ${modulePath} not found, skipping...`)
			continue
		}

		const content = fs.readFileSync(modulePath, "utf-8")
		const exports = extractExports(content)

		output += `// ============================================================\n`
		output += `// ${module.name.toUpperCase()} MODULE\n`
		output += `// ============================================================\n\n`
		output += exports
		output += "\n\n"
	}

	// Add initialization functions
	output += `// ============================================================\n`
	output += `// INITIALIZATION FUNCTIONS\n`
	output += `// ============================================================\n\n`
	output += `export function initTaskEngine(): Promise<void>\n`
	output += `export function initTools(): Promise<void>\n`
	output += `export function initApiIntegration(): Promise<void>\n`
	output += `export function initConversation(): Promise<void>\n`
	output += `export function initMemory(): Promise<void>\n`
	output += `export function initAll(): Promise<void>\n`

	return output
}

// Main execution
try {
	console.log("🔧 Merging WASM type definitions...")

	const unifiedTypes = generateUnifiedTypes()

	// Ensure output directory exists
	const outputDir = path.dirname(OUTPUT_FILE)
	if (!fs.existsSync(outputDir)) {
		fs.mkdirSync(outputDir, { recursive: true })
	}

	// Write unified types
	fs.writeFileSync(OUTPUT_FILE, unifiedTypes, "utf-8")

	console.log(`✅ Successfully generated ${OUTPUT_FILE}`)
	console.log(`📦 Merged ${MODULES.length} WASM modules`)
} catch (error) {
	console.error("❌ Error merging WASM types:", error)
	process.exit(1)
}
